import bisect
from collections import deque, defaultdict
import heapq

class StatisticsTracker:
    def __init__(self):
        self.q = deque()
        self.sorted_nums = []
        self.total_sum = 0
        self.freq = defaultdict(int)
        self.mode_heap = []

    def addNumber(self, number: int) -> None:
        self.q.append(number)
        bisect.insort(self.sorted_nums, number)
        self.total_sum += number
        self.freq[number] += 1
        heapq.heappush(self.mode_heap, (-self.freq[number], number))

    def removeFirstAddedNumber(self) -> None:
        x = self.q.popleft()
        idx = bisect.bisect_left(self.sorted_nums, x)
        self.sorted_nums.pop(idx)
        self.total_sum -= x
        self.freq[x] -= 1
        if self.freq[x] > 0:
            heapq.heappush(self.mode_heap, (-self.freq[x], x))

    def getMean(self) -> int:
        return self.total_sum // len(self.q)

    def getMedian(self) -> int:
        return self.sorted_nums[len(self.sorted_nums) // 2]

    def getMode(self) -> int:
        while self.mode_heap:
            neg_f, num = self.mode_heap[0]
            if -neg_f == self.freq[num]:
                return num
            heapq.heappop(self.mode_heap)
        return -1

class StatisticsTracker {
private:
    queue<int> q;
    vector<int> sortedNums;
    long long totalSum = 0;
    unordered_map<int, int> freq;
    priority_queue<pair<int, int>> modeHeap;

public:
    StatisticsTracker() {}

    void addNumber(int number) {
        q.push(number);
        auto it = lower_bound(sortedNums.begin(), sortedNums.end(), number);
        sortedNums.insert(it, number);
        totalSum += number;
        freq[number]++;
        modeHeap.push({freq[number], -number});
    }

    void removeFirstAddedNumber() {
        int x = q.front();
        q.pop();
        auto it = lower_bound(sortedNums.begin(), sortedNums.end(), x);
        sortedNums.erase(it);
        totalSum -= x;
        freq[x]--;
        if (freq[x] > 0) {
            modeHeap.push({freq[x], -x});
        }
    }

    int getMean() {
        return totalSum / q.size();
    }

    int getMedian() {
        return sortedNums[sortedNums.size() / 2];
    }

    int getMode() {
        while (!modeHeap.empty()) {
            auto [f, negNum] = modeHeap.top();
            int num = -negNum;
            if (f == freq[num]) return num;
            modeHeap.pop();
        }
        return -1;
    }
};

class StatisticsTracker {
    private Queue<Integer> q;
    private List<Integer> sortedNums;
    private long totalSum = 0;
    private Map<Integer, Integer> freq;
    private PriorityQueue<int[]> modeHeap;

    public StatisticsTracker() {
        q = new ArrayDeque<>();
        sortedNums = new ArrayList<>();
        freq = new HashMap<>();
        modeHeap = new PriorityQueue<>((a, b) -> {
            if (a[0] != b[0]) return Integer.compare(b[0], a[0]);
            return Integer.compare(a[1], b[1]);
        });
    }

    public void addNumber(int number) {
        q.offer(number);
        int idx = Collections.binarySearch(sortedNums, number);
        if (idx < 0) idx = -(idx + 1);
        sortedNums.add(idx, number);
        totalSum += number;
        int f = freq.getOrDefault(number, 0) + 1;
        freq.put(number, f);
        modeHeap.offer(new int[]{f, number});
    }

    public void removeFirstAddedNumber() {
        int x = q.poll();
        int idx = Collections.binarySearch(sortedNums, x);
        sortedNums.remove(idx);
        totalSum -= x;
        int f = freq.get(x) - 1;
        if (f == 0) freq.remove(x);
        else {
            freq.put(x, f);
            modeHeap.offer(new int[]{f, x});
        }
    }

    public int getMean() {
        return (int) (totalSum / q.size());
    }

    public int getMedian() {
        return sortedNums.get(sortedNums.size() / 2);
    }

    public int getMode() {
        while (!modeHeap.isEmpty()) {
            int[] top = modeHeap.peek();
            int f = top[0];
            int num = top[1];
            if (freq.getOrDefault(num, 0) == f) return num;
            modeHeap.poll();
        }
        return -1;
    }
}

var StatisticsTracker = function() {
    this.q = [];
    this.sortedNums = [];
    this.totalSum = 0;
    this.freq = new Map();
};

StatisticsTracker.prototype.addNumber = function(number) {
    this.q.push(number);
    let l = 0, r = this.sortedNums.length;
    while (l < r) {
        const mid = (l + r) >> 1;
        if (this.sortedNums[mid] < number) l = mid + 1;
        else r = mid;
    }
    this.sortedNums.splice(l, 0, number);
    this.totalSum += number;
    this.freq.set(number, (this.freq.get(number) || 0) + 1);
};

StatisticsTracker.prototype.removeFirstAddedNumber = function() {
    const x = this.q.shift();
    let l = 0, r = this.sortedNums.length;
    while (l < r) {
        const mid = (l + r) >> 1;
        if (this.sortedNums[mid] < x) l = mid + 1;
        else r = mid;
    }
    this.sortedNums.splice(l, 1);
    this.totalSum -= x;
    const f = this.freq.get(x) - 1;
    if (f === 0) this.freq.delete(x);
    else this.freq.set(x, f);
};

StatisticsTracker.prototype.getMean = function() {
    return Math.floor(this.totalSum / this.q.length);
};

StatisticsTracker.prototype.getMedian = function() {
    return this.sortedNums[Math.floor(this.sortedNums.length / 2)];
};

StatisticsTracker.prototype.getMode = function() {
    let bestFreq = 0;
    let bestNum = Infinity;
    for (const [num, f] of this.freq.entries()) {
        if (f > bestFreq || (f === bestFreq && num < bestNum)) {
            bestFreq = f;
            bestNum = num;
        }
    }
    return bestNum;
};
